(() => {
  (typeof ngDevMode === "undefined" || ngDevMode) && setClassMetadata(StaffListComponent, [{
    type: Component,
    args: [{ selector: "app-staff-list", standalone: true, imports: [
      CommonModule,
      ReactiveFormsModule,
      MatButtonModule,
      MatFormFieldModule,
      MatIconModule,
      MatMenuModule,
      MatSelectModule,
      MatTooltipModule,
      MatProgressSpinnerModule,
      MatDialogModule,
      TranslocoModule,
      RouterModule,
      SettingsBusinessAccountEmptyStateComponent
    ], encapsulation: ViewEncapsulation.None, changeDetection: ChangeDetectionStrategy.OnPush, template: `<div class="flex flex-col h-full min-h-[calc(100vh-200px)]">\r
    <!-- Panel Header -->\r
    <div class="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">\r
        <div>\r
            <h1 class="text-2xl font-bold text-gray-900 dark:text-white">\r
                {{ 'settings.team.title' | transloco }}\r
            </h1>\r
            <p class="mt-2 text-gray-600 dark:text-gray-400">\r
                {{ 'settings.team.subtitle' | transloco }}\r
            </p>\r
        </div>\r
\r
        <button\r
            *ngIf="userClientId && (!user?.staff || user?.role === 'administrador')"\r
            mat-flat-button\r
            color="primary"\r
            class="!bg-blue-600 hover:!bg-blue-700 text-white rounded-lg px-6 h-10"\r
            [class.!bg-gray-400]="!canAddMoreStaff()"\r
            [class.hover:!bg-gray-400]="!canAddMoreStaff()"\r
            [class.cursor-not-allowed]="!canAddMoreStaff()"\r
            (click)="canAddMoreStaff() ? openStaffModal() : null"\r
            [matTooltip]="!canAddMoreStaff() ? ('settings.team.limit_reached' | transloco) : ''"\r
        >\r
            <mat-icon class="mr-2" style="width: 20px; height: 20px; font-size: 20px">add</mat-icon>\r
            {{ 'settings.team.add_member' | transloco }}\r
        </button>\r
    </div>\r
\r
    <app-settings-business-account-empty-state\r
        *ngIf="!userClientId"\r
        hintKey="settings.team.sign_in_hint"\r
        (userChange)="onBusinessAccountLinked($event)"\r
    />\r
\r
    <ng-container *ngIf="userClientId">\r
    <!-- Staff Limit Alert -->\r
    <div *ngIf="selectedSubscription && staffLoaded" class="mb-6">\r
        <div\r
            class="rounded-xl p-4 flex items-start gap-4"\r
            [ngClass]="{\r
                'bg-blue-50 border border-blue-100 dark:bg-blue-900/20 dark:border-blue-800':\r
                    hasSubscription && canAddMoreStaff(),\r
                'bg-amber-50 border border-amber-100 dark:bg-amber-900/20 dark:border-amber-800':\r
                    hasSubscription && !canAddMoreStaff(),\r
                'bg-red-50 border border-red-100 dark:bg-red-900/20 dark:border-red-800':\r
                    !hasSubscription,\r
            }"\r
        >\r
            <mat-icon\r
                class="mt-0.5"\r
                [ngClass]="{\r
                    'text-blue-600 dark:text-blue-400': hasSubscription && canAddMoreStaff(),\r
                    'text-amber-600 dark:text-amber-400': hasSubscription && !canAddMoreStaff(),\r
                    'text-red-600 dark:text-red-400': !hasSubscription,\r
                }"\r
                style="width: 24px; height: 24px; font-size: 24px"\r
                >info</mat-icon\r
            >\r
            <div class="text-sm">\r
                <p\r
                    [ngClass]="{\r
                        'text-blue-900 dark:text-blue-100': hasSubscription && canAddMoreStaff(),\r
                        'text-amber-900 dark:text-amber-100': hasSubscription && !canAddMoreStaff(),\r
                        'text-red-900 dark:text-red-100': !hasSubscription,\r
                    }"\r
                >\r
                    <ng-container *ngIf="hasSubscription">\r
                        {{ 'settings.team.limit_info_1' | transloco }}\r
                        <span class="font-bold">{{\r
                            selectedSubscription.name === 'PyG' ? 'PAYG' : selectedSubscription.name\r
                        }}</span>\r
                        {{ 'settings.team.limit_info_2' | transloco }}\r
                        <span class="font-bold">{{ staffLimit }}</span>\r
                        {{ 'settings.team.limit_info_3' | transloco }}\r
                        (<span class="font-semibold"\r
                            >{{ staffMembers.length }}/{{ staffLimit }}</span\r
                        >\r
                        {{ 'settings.team.used' | transloco }})\r
                    </ng-container>\r
                    <ng-container *ngIf="!hasSubscription">\r
                        {{ 'settings.team.no_plan_warning' | transloco }}\r
                    </ng-container>\r
                    <a\r
                        routerLink="/subscription-plans"\r
                        class="underline hover:opacity-80 ml-1 font-medium"\r
                        [ngClass]="{\r
                            'text-blue-700 dark:text-blue-300':\r
                                hasSubscription && canAddMoreStaff(),\r
                            'text-amber-700 dark:text-amber-300':\r
                                hasSubscription && !canAddMoreStaff(),\r
                            'text-red-700 dark:text-red-300': !hasSubscription,\r
                        }"\r
                    >\r
                        {{ 'settings.team.view_plans' | transloco }}\r
                    </a>\r
                </p>\r
            </div>\r
        </div>\r
    </div>\r
\r
    <div *ngIf="isLoadingStaff" class="flex-1 flex items-center justify-center py-12">\r
        <mat-spinner diameter="32"></mat-spinner>\r
    </div>\r
\r
    <!-- Staff List -->\r
    <div\r
        *ngIf="staffLoaded && !isLoadingStaff"\r
        class="content-card overflow-hidden flex-1 flex flex-col"\r
    >\r
        <!-- List Header -->\r
        <div\r
            class="hidden md:grid grid-cols-12 gap-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50 px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wider"\r
        >\r
            <div class="col-span-4">{{ 'settings.team.name' | transloco }}</div>\r
            <div class="col-span-3">\r
                {{ 'settings.team.email_label' | transloco }}\r
            </div>\r
            <div class="col-span-2">{{ 'settings.team.status' | transloco }}</div>\r
            <div class="col-span-2">{{ 'settings.team.role' | transloco }}</div>\r
            <div class="col-span-1 text-right">\r
                {{ 'settings.team.actions' | transloco }}\r
            </div>\r
        </div>\r
\r
        <!-- List Body -->\r
        <div class="divide-y divide-gray-100 dark:divide-gray-700">\r
            <ng-container *ngFor="let staff of staffMembers">\r
                <div\r
                    class="grid grid-cols-1 md:grid-cols-12 gap-4 px-6 py-4 items-center hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors"\r
                >\r
                    <!-- Name -->\r
                    <div class="col-span-4 flex items-center gap-3">\r
                        <div\r
                            class="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 text-white flex items-center justify-center font-bold text-sm overflow-hidden shrink-0"\r
                        >\r
                            <img\r
                                *ngIf="staff.avatar"\r
                                [src]="staff.avatar"\r
                                class="w-full h-full object-cover"\r
                            />\r
                            <span *ngIf="!staff.avatar">{{ getStaffInitials(staff.name) }}</span>\r
                        </div>\r
                        <div class="font-medium text-gray-900 dark:text-white truncate">\r
                            {{ staff.name }}\r
                        </div>\r
                    </div>\r
\r
                    <!-- Email -->\r
                    <div\r
                        class="col-span-3 text-sm text-gray-600 dark:text-gray-400 truncate"\r
                        [matTooltip]="staff.email"\r
                    >\r
                        {{ truncateEmail(staff.email, 25) }}\r
                    </div>\r
\r
                    <!-- Status -->\r
                    <div class="col-span-2">\r
                        <span\r
                            class="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium"\r
                            [ngClass]="{\r
                                'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400':\r
                                    staff.status === 'active',\r
                                'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400':\r
                                    staff.status !== 'active',\r
                            }"\r
                        >\r
                            {{ 'settings.team.status_' + (staff.status || 'pending') | transloco }}\r
                        </span>\r
                    </div>\r
\r
                    <!-- Role -->\r
                    <div class="col-span-2 text-sm text-gray-600 dark:text-gray-400 capitalize">\r
                        {{ 'settings.team.role_' + staff.role | transloco }}\r
                    </div>\r
\r
                    <!-- Actions -->\r
                    <div class="col-span-1 flex justify-end">\r
                        <button\r
                            mat-icon-button\r
                            [matMenuTriggerFor]="staffMenu"\r
                            *ngIf="!user?.staff || user?.role === 'administrador'"\r
                        >\r
                            <mat-icon class="text-gray-400">more_vert</mat-icon>\r
                        </button>\r
                        <mat-menu #staffMenu="matMenu">\r
                            <button mat-menu-item (click)="openStaffModal(staff)">\r
                                <mat-icon class="text-gray-400 mr-2">edit</mat-icon>\r
                                {{ 'settings.team.edit' | transloco }}\r
                            </button>\r
                            <button mat-menu-item (click)="reinviteStaff(staff)">\r
                                <mat-icon class="text-gray-400 mr-2">send</mat-icon>\r
                                {{ 'settings.team.reinvite' | transloco }}\r
                            </button>\r
                            <button mat-menu-item class="text-red-600" (click)="deleteStaff(staff)">\r
                                <mat-icon class="text-red-400 mr-2">delete</mat-icon>\r
                                {{ 'settings.team.remove' | transloco }}\r
                            </button>\r
                        </mat-menu>\r
                    </div>\r
                </div>\r
            </ng-container>\r
\r
            <!-- Empty State -->\r
            <div\r
                *ngIf="!staffMembers?.length"\r
                class="flex-1 p-12 flex flex-col items-center justify-center text-center"\r
            >\r
                <div\r
                    class="w-16 h-16 bg-gray-50 dark:bg-gray-800 rounded-full flex items-center justify-center mb-4"\r
                >\r
                    <mat-icon\r
                        class="text-gray-400"\r
                        style="width: 32px; height: 32px; font-size: 32px"\r
                        >group</mat-icon\r
                    >\r
                </div>\r
                <h3 class="text-lg font-medium text-gray-900 dark:text-white">\r
                    {{ 'settings.team.no_members' | transloco }}\r
                </h3>\r
                <p class="text-gray-500 mt-1 max-w-sm">\r
                    {{ 'settings.team.no_members_desc' | transloco }}\r
                </p>\r
            </div>\r
        </div>\r
        <!-- end divide-y list body -->\r
    </div>\r
    <!-- end content-card -->\r
    </ng-container>\r
</div>\r
\r
<!-- Staff Form Dialog -->\r
<ng-template #staffFormDialog>\r
    <div class="staff-dialog flex flex-col bg-white dark:bg-gray-900">\r
        <!-- Modal Header -->\r
        <div\r
            class="flex items-center justify-between p-6 border-b border-gray-100 dark:border-gray-700"\r
        >\r
            <h2 class="text-xl font-bold text-gray-900 dark:text-white">\r
                {{\r
                    (editingStaff ? 'settings.team.edit_member' : 'settings.team.add_member')\r
                        | transloco\r
                }}\r
            </h2>\r
        </div>\r
\r
        <!-- Modal Body -->\r
        <div class="flex-1 p-6 flex flex-col gap-5 overflow-y-auto" [formGroup]="staffForm">\r
            <p class="text-sm text-gray-500 mb-2">\r
                {{ 'settings.team.form_description' | transloco }}\r
            </p>\r
\r
            <!-- Name -->\r
            <div class="flex flex-col gap-1.5">\r
                <label class="text-sm font-semibold text-gray-700 dark:text-gray-300">\r
                    {{ 'settings.team.full_name' | transloco }}\r
                </label>\r
                <input\r
                    type="text"\r
                    formControlName="name"\r
                    class="h-11 px-4 bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 w-full text-gray-900 dark:text-white"\r
                    placeholder="e.g. John Doe"\r
                />\r
            </div>\r
\r
            <!-- Email -->\r
            <div class="flex flex-col gap-1.5">\r
                <label class="text-sm font-semibold text-gray-700 dark:text-gray-300">\r
                    {{ 'settings.team.email' | transloco }}\r
                </label>\r
                <input\r
                    type="email"\r
                    formControlName="email"\r
                    class="h-11 px-4 bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 w-full text-gray-900 dark:text-white"\r
                    placeholder="e.g. john@example.com"\r
                />\r
            </div>\r
\r
            <div class="grid grid-cols-2 gap-4">\r
                <!-- Country Code (searchable; matches auth-modal pattern) -->\r
                <div class="flex flex-col gap-1.5">\r
                    <label class="text-sm font-semibold text-gray-700 dark:text-gray-300">\r
                        {{ 'settings.team.country_code' | transloco }}\r
                    </label>\r
                    <div class="relative staff-country-picker">\r
                        <button\r
                            type="button"\r
                            (click)="toggleStaffCountryDropdown($event)"\r
                            class="h-11 w-full px-3 rounded-lg border border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-800 text-gray-900 dark:text-white flex items-center justify-between gap-2 hover:bg-gray-100 dark:hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"\r
                        >\r
                            <span class="flex items-center gap-2 text-sm min-w-0 flex-1">\r
                                <ng-container *ngIf="getSelectedStaffCountry() as sel">\r
                                    <span class="shrink-0">{{ sel.flag }}</span>\r
                                    <span class="font-medium shrink-0">{{ sel.dialCode }}</span>\r
                                    <span class="text-gray-500 dark:text-gray-400 truncate">{{\r
                                        sel.name\r
                                    }}</span>\r
                                </ng-container>\r
                                <span\r
                                    *ngIf="!getSelectedStaffCountry()"\r
                                    class="text-gray-400 text-sm"\r
                                >\r
                                    {{ 'authModal.phoneInput.selectCountry' | transloco }}\r
                                </span>\r
                            </span>\r
                            <mat-icon class="!w-5 !h-5 !text-[20px] text-gray-400 shrink-0"\r
                                >arrow_drop_down</mat-icon\r
                            >\r
                        </button>\r
                        <div\r
                            *ngIf="isStaffCountryDropdownOpen && staffCountryDropdownPosition"\r
                            class="fixed z-[1000] w-[min(calc(100vw-2rem),20rem)] max-h-80 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg shadow-lg overflow-hidden"\r
                            [style.top]="staffCountryDropdownPosition.top"\r
                            [style.left]="staffCountryDropdownPosition.left"\r
                            (click)="$event.stopPropagation()"\r
                        >\r
                            <div class="p-2 border-b border-gray-200 dark:border-gray-700">\r
                                <div class="relative">\r
                                    <mat-icon\r
                                        class="absolute left-2 top-1/2 -translate-y-1/2 !w-4 !h-4 !text-[16px] text-gray-400"\r
                                        >search</mat-icon\r
                                    >\r
                                    <input\r
                                        type="text"\r
                                        [value]="staffCountrySearchTerm"\r
                                        (input)="onStaffCountrySearchChange($any($event.target).value)"\r
                                        [placeholder]="'authModal.phoneInput.searchCountry' | transloco"\r
                                        class="w-full pl-8 pr-3 py-2 text-sm rounded-md border border-gray-300 dark:border-gray-600 bg-transparent text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500/20 focus:outline-none"\r
                                    />\r
                                </div>\r
                            </div>\r
                            <div class="max-h-64 overflow-y-auto">\r
                                <button\r
                                    *ngFor="let country of filteredStaffCountryCodes"\r
                                    type="button"\r
                                    (click)="selectStaffCountry(country)"\r
                                    class="w-full px-4 py-3 flex items-center gap-3 hover:bg-gray-50 dark:hover:bg-gray-700 text-left transition-colors"\r
                                    [ngClass]="{\r
                                        'bg-blue-50 dark:bg-blue-900/30':\r
                                            isStaffCountryRowSelected(country),\r
                                    }"\r
                                >\r
                                    <span class="text-2xl shrink-0">{{ country.flag }}</span>\r
                                    <div class="flex-1 min-w-0">\r
                                        <div\r
                                            class="text-sm font-medium text-gray-900 dark:text-gray-100 truncate"\r
                                        >\r
                                            {{ country.name }}\r
                                        </div>\r
                                    </div>\r
                                    <span\r
                                        class="text-sm text-gray-500 dark:text-gray-400 font-medium shrink-0"\r
                                        >{{ country.dialCode }}</span\r
                                    >\r
                                </button>\r
                                <div\r
                                    *ngIf="filteredStaffCountryCodes.length === 0"\r
                                    class="px-4 py-3 text-sm text-gray-500 text-center"\r
                                >\r
                                    {{ 'authModal.phoneInput.noCountries' | transloco }}\r
                                </div>\r
                            </div>\r
                        </div>\r
                    </div>\r
                </div>\r
\r
                <!-- Phone -->\r
                <div class="flex flex-col gap-1.5">\r
                    <label class="text-sm font-semibold text-gray-700 dark:text-gray-300">\r
                        {{ 'settings.team.phone' | transloco }}\r
                    </label>\r
                    <input\r
                        type="tel"\r
                        formControlName="phone"\r
                        class="h-11 px-4 bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 w-full text-gray-900 dark:text-white"\r
                    />\r
                </div>\r
            </div>\r
\r
            <!-- Role -->\r
            <mat-form-field\r
                class="w-full staff-role-field"\r
                appearance="outline"\r
                subscriptSizing="dynamic"\r
            >\r
                <mat-label>{{ 'settings.team.role' | transloco }}</mat-label>\r
                <mat-select formControlName="role" panelClass="staff-role-panel">\r
                    <mat-option value="empleado">{{\r
                        'settings.team.role_empleado' | transloco\r
                    }}</mat-option>\r
                    <mat-option value="contabilidad">{{\r
                        'settings.team.role_contabilidad' | transloco\r
                    }}</mat-option>\r
                    <mat-option value="desarrollador">{{\r
                        'settings.team.role_desarrollador' | transloco\r
                    }}</mat-option>\r
                    <mat-option value="administrador">{{\r
                        'settings.team.role_administrador' | transloco\r
                    }}</mat-option>\r
                </mat-select>\r
            </mat-form-field>\r
        </div>\r
\r
        <!-- Modal Footer -->\r
        <div\r
            class="p-6 border-t border-gray-100 dark:border-gray-700 flex items-center justify-end gap-3 bg-gray-50/50 dark:bg-gray-800/50"\r
        >\r
            <button mat-stroked-button (click)="closeStaffDialog()">\r
                {{ 'settings.team.cancel' | transloco }}\r
            </button>\r
            <button\r
                mat-flat-button\r
                color="primary"\r
                [disabled]="isSavingStaff || staffForm.invalid"\r
                class="!bg-blue-600 hover:!bg-blue-700 text-white"\r
                (click)="saveStaff()"\r
            >\r
                <mat-spinner *ngIf="isSavingStaff" diameter="18" class="mr-2"></mat-spinner>\r
                {{\r
                    isSavingStaff\r
                        ? ('settings.team.saving' | transloco)\r
                        : ('settings.team.save' | transloco)\r
                }}\r
            </button>\r
        </div>\r
    </div>\r
</ng-template>\r
` }]
  }], () => [{ type: ChangeDetectorRef }, { type: SettingsService }, { type: FormBuilder }, { type: CountryService }, { type: MatDialog }, { type: MatSnackBar }, { type: TranslocoService }], { user: [{
    type: Input
  }], staffChanged: [{
    type: Output
  }], userChange: [{
    type: Output
  }], staffFormDialog: [{
    type: ViewChild,
    args: ["staffFormDialog"]
  }], onDocumentClick: [{
    type: HostListener,
    args: ["document:click", ["$event"]]
  }] });
})();
